(10, 'aire-tierra-y-mar', 'Aire, Tierra y Mar', 2, 2, 20, null, 2, 10, 'Cartas', 'Duelo con solo 18 cartas en tres teatros de guerra; se puede jugar boca abajo como farol y retirarse a tiempo para ceder menos puntos.', 'Juego de cartas pequeño y rápido de colocación de cartas y mayorías.', array['Retirarse pronto de una ronda perdida es parte de la estrategia', 'Una carta boca abajo vale 2 y se puede jugar en cualquier teatro'], 'https://juegoscadabra.com/wp-content/uploads/2025/11/AIRE-TIERRA-Y-MAR-1.png', 10398, 'https://juegoscadabra.com/product/aire-tierra-y-mar/', 'catalogo', false, true),
(11, 'akropolis', 'Akropolis', 2, 4, 25, null, 2, 8, 'Familiar', 'Colocación de losetas en altura para construir una ciudad griega: cada barrio puntúa según sus plazas y el nivel al que está.', 'Juego de puzzle y colocación de losas para construir una ciudad griega.', array['Sin plazas de su color, un barrio no puntúa', 'Construir en altura multiplica el valor de los barrios'], 'https://juegoscadabra.com/wp-content/uploads/2025/11/AKROPOLIS-1.png', 10400, 'https://juegoscadabra.com/product/akropolis/', 'catalogo', false, true),
